│   └── ...
├── Application/
│   ├── Order/
│   │   ├── OrderRegistrationService.php
│   │   └── CreateOrderData.php
│   └── ...
├── Infrastructure/
│   ├── Doctrine/
│   │   └── DoctrineOrderRepository.php
│   └── ...
